function fig = plot_summary_by_regime_all_dma(Lib, dma_values, i_ref, cmap_dma, baseFont, titleFont, lineWidthCurve, lineWidthRef, lineWidthExp, markerSizeExp, figColor, gridAlpha)
    reg_order = ["turnover-dominated","mixed","resource-dominated"];
    fig = figure('Units','centimeters','Position',[2 2 30 16],'Color',figColor);
    tiledlayout(2,2,'TileSpacing','compact','Padding','compact');

    for iR = 1:3
        nexttile; hold on;
        mask = strcmp(string({Lib.TU.regime_ref}), reg_order(iR));
        X = Lib.TU(mask);

        for k = 1:numel(X)
            fill([X(k).mu_grid_ref; flipud(X(k).mu_grid_ref)], [X(k).ratio_q25; flipud(X(k).ratio_q75)], X(k).color, ...
                'FaceAlpha', 0.08, 'EdgeColor', 'none');
            plot(X(k).mu_grid_ref, X(k).ratio_by_dmA{i_ref}, '-', 'LineWidth', lineWidthRef, 'Color', X(k).color);
            scatter(median(X(k).mu_exp_by_dmA{i_ref}), X(k).ratio_exp_median_by_dmA(i_ref), 28, ...
                'MarkerFaceColor', X(k).color, 'MarkerEdgeColor', 'k', 'LineWidth', 0.35);
        end

        yline(1, '--', 'Color', [0.2 0.2 0.2], 'LineWidth', lineWidthExp);
        title(sprintf('%s (n=%d)', char(reg_order(iR)), numel(X)), 'Interpreter','none', 'FontSize', titleFont);
        xlabel('\mu (min^{-1})');
        ylabel('ratio');
        grid on; box on;
        ax = gca;
        set(ax, 'FontSize', baseFont, 'LineWidth', 1.0, 'Layer', 'top');
        ax.GridAlpha = gridAlpha;
        ax.MinorGridAlpha = gridAlpha*0.9;
    end

    nexttile; hold on;
    for iR = 1:3
        mask = strcmp(string({Lib.TU.regime_ref}), reg_order(iR));
        X = Lib.TU(mask);
        if isempty(X), continue; end

        med_stack = nan(numel(X), numel(dma_values));
        for kk = 1:numel(X)
            med_stack(kk,:) = X(kk).ratio_exp_median_by_dmA(:)';
        end
        y = mean(med_stack,1);
        yq25 = prctile(med_stack,25,1);
        yq75 = prctile(med_stack,75,1);

        if iR == 1
            col = [0.70 0.85 0.70];
        elseif iR == 2
            col = [0.95 0.85 0.55];
        else
            col = [0.80 0.80 0.90];
        end

        xfill = [dma_values(:); flipud(dma_values(:))];
        yfill = [yq25(:); flipud(yq75(:))];
        if numel(xfill) == numel(yfill) && all(isfinite(yfill))
            fill(xfill, yfill, col, ...
                'FaceAlpha', 0.18, 'EdgeColor', 'none');
        end;
        plot(dma_values, y, '-', 'LineWidth', 1.8, 'Color', col*0.75);
        plot(dma_values(i_ref), y(i_ref), 'kd', 'MarkerFaceColor', 'w', 'MarkerSize', 4.5);
    end
    xlabel('d_{mA} (min^{-1})');
    ylabel('mean TU median ratio');
    title('Per-regime summary across d_{mA}', 'FontSize', titleFont);
    grid on; box on;
    ax = gca;
    set(ax, 'FontSize', baseFont, 'LineWidth', 1.0, 'Layer', 'top');
    ax.GridAlpha = gridAlpha;
    ax.MinorGridAlpha = gridAlpha*0.9;

    sgtitle('Lib30: ratio summary grouped by regime across d_{mA}', ...
        'FontSize', titleFont+1, 'FontWeight', 'bold');
end

function txt = compose_title(X)
    name = string(X.TU_Name);
    if strlength(name) == 0
        parts = [string(X.TU_Ori), string(X.TU_Promoter), string(X.TU_RBS)];
        parts = parts(parts ~= "");
        txt = strjoin(parts, ' | ');
    else
        txt = name;
    end
end

function export_figure(fig_handle, file_base)
    set(fig_handle, 'PaperPositionMode', 'auto');
    drawnow;
    exportgraphics(fig_handle, [file_base '.png'], 'Resolution', 300);
    exportgraphics(fig_handle, [file_base '.svg'], 'ContentType', 'vector');
end

function c = hex2rgb(hex)
    hex = char(hex);
    hex = strrep(hex, '#', '');
    if numel(hex) ~= 6
        error('hex2rgb:InvalidInput', 'Expected a 6-character hex code.');
    end
    c = [hex2dec(hex(1:2)), hex2dec(hex(3:4)), hex2dec(hex(5:6))] / 255;
end
